const assert = require('node:assert/strict');
const supertest = require('supertest');
const testUtils = require('../../utils');
const localUtils = require('./utils');
const config = require('../../../core/shared/config');

describe('Audit Logs API', function () {
    let request;

    before(async function () {
        await localUtils.startGhost();
        request = supertest.agent(config.get('url'));
        await localUtils.doAuth(request, 'integrations', 'api_keys');
    });

    it('Can browse audit logs', async function () {
        const res = await request
            .get(localUtils.API.getApiQuery('audit_logs/'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(200);

        assert.ok(res.body.audit_logs);
        assert.ok(Array.isArray(res.body.audit_logs));
    });

    it('Can browse audit logs with pagination', async function () {
        const res = await request
            .get(localUtils.API.getApiQuery('audit_logs/?limit=5&page=1'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(200);

        assert.ok(res.body.audit_logs);
        assert.ok(Array.isArray(res.body.audit_logs));
        assert.ok(res.body.meta);
        assert.ok(res.body.meta.pagination);
    });

    it('Returns 401 for unauthenticated requests', async function () {
        const unauthenticatedRequest = supertest.agent(config.get('url'));

        await unauthenticatedRequest
            .get(localUtils.API.getApiQuery('audit_logs/'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect(401);
    });
});

